window.AponarQuartet2Data={"q2":{"chapters.theme_bn":{"প্রসঙ্গ, পরোক্ষ কথা ও ভাষার সূক্ষ্ম পার্থক্য":"Ngữ cảnh, lời nói gián tiếp và sự khác biệt tinh tế của ngôn ngữ","যুক্তি, বিকল্প দৃষ্টিকোণ ও মতামত গঠন":"Lập luận, góc nhìn thay thế và hình thành ý kiến","অভিজ্ঞতা থেকে শেখা ও ভদ্রভাবে মতের পার্থক্য বলা":"Học từ trải nghiệm và nói sự khác biệt ý kiến một cách lịch sự","কাজের মূল্যবোধ, সাক্ষাৎকার নেওয়া ও তথ্য সাজানো":"Giá trị quan của công việc, phỏng vấn và sắp xếp thông tin","ঘটনার মোড়, উপমা ও অনুভূতির পরিবর্তন পড়া":"Đọc bước ngoặt của sự kiện, phép ẩn dụ và sự thay đổi cảm xúc","তুলনা, পরিবর্তনের প্রবণতা ও সীমিত সিদ্ধান্ত":"So sánh, xu hướng thay đổi và kết luận có giới hạn"},"chapters.title_bn":{"অধ্যায় ৮ · পেশাদারিত্ব ও সাক্ষাৎকার":"Chương 8 · Tính chuyên nghiệp và phỏng vấn","অধ্যায় ১০ · তথ্য দিয়ে সমাজ বোঝা":"Chương 10 · Hiểu xã hội qua dữ liệu","অধ্যায় ৯ · গল্প, অনুভূতি ও পর্যালোচনা":"Chương 9 · Câu chuyện, cảm xúc và nhìn lại","অধ্যায় ১২ · চিন্তার পরিবর্তন ও সমাজ":"Chương 12 · Sự thay đổi tư duy và xã hội","অধ্যায় ১১ · শব্দের আড়ালের অর্থ":"Chương 11 · Ý nghĩa ẩn sau từ ngữ","অধ্যায় ৭ · ভিন্ন সংস্কৃতি, নতুন উপলব্ধি":"Chương 7 · Văn hóa khác biệt, nhận thức mới"},"form_guide.label":{"সম্ভাব্য রূপ":"Dạng khả năng","い-বিশেষণ":"い-tính từ (tính từ i)","な-বিশেষণ":"な-tính từ (tính từ na)","ইচ্ছার রূপ":"Dạng ý chí"},"form_guide.meaning_bn":{"বর্তমান বা ভবিষ্যতের সাধারণ নেতিবাচক রূপ।":"Dạng phủ định thông thường ở hiện tại hoặc tương lai.","ます・です ছাড়া সাধারণ রূপ: বর্তমান, অতীত, ইতিবাচক ও নেতিবাচক। N ও な-বিশেষণের だ কখন বাদ/な/の হবে তা প্রতিটি নিয়মে দেওয়া আছে।":"Dạng thông thường không có ます・です: hiện tại, quá khứ, khẳng định và phủ định. Việc だ của N và な-tính từ khi nào bị lược bỏ / thành な / thành の được nêu trong từng quy tắc.","বিশেষ্যকে বর্ণনা করলে な লাগে। সব গঠনে な থাকবে না; পাঠের সংযোগ দেখুন।":"Khi bổ nghĩa cho danh từ thì thêm な. Không phải cấu trúc nào cũng có な; hãy xem cách nối trong bài học.","সাধারণ অতীত রূপ।":"Dạng quá khứ thông thường.","ます-রূপ থেকে শুধু ます বাদ দিন।":"Chỉ cần bỏ ます khỏi dạng ます.","“করি/করব” ধরনের volitional form।":"Volitional form kiểu \"tôi sẽ làm / hãy làm\".","ক্রিয়ার সংযোগের て-form; কোথাও で হয়।":"て-form dùng để nối động từ; ở một số nơi thành で.","কোনো কাজ করতে পারা বোঝায়।":"Diễn tả việc có thể làm một việc gì đó.","বিশেষ্য: ব্যক্তি, বস্তু বা বিষয়ের নাম।":"Danh từ: tên của người, vật hoặc sự việc.","い-বিশেষণ, যেমন বড়, দামি। নেতিবাচক ও অতীতে রূপ বদলায়।":"い-tính từ, ví dụ như 'lớn', 'đắt'. Hình thức thay đổi ở phủ định và quá khứ.","ক্রিয়ার dictionary form; এর মানে সব ক্রিয়া る দিয়ে শেষ হবে না।":"Dạng từ điển của động từ; điều này không có nghĩa mọi động từ đều kết thúc bằng る.","শর্তের ば-form।":"ば-form của điều kiện."},"lessons.examples.bangla":{"সংস্কৃতি আলাদা বলেই আলোচনা করা জরুরি।":"Chính vì văn hóa khác nhau nên việc thảo luận là cần thiết.","তিনি শিক্ষক বলার চেয়ে বরং বন্ধুর মতো।":"Thay vì nói là giáo viên, anh ấy giống như một người bạn hơn.","আগামীকাল হলে সাহায্য করা একেবারে অসম্ভব নয়।":"Nếu là ngày mai, việc giúp đỡ không phải hoàn toàn không thể.","বয়স বাড়ার সঙ্গে চিন্তার ধরনও বদলায়।":"Cùng với tuổi tác tăng lên, cách suy nghĩ cũng thay đổi.","শিশুটি কাঁদল মনে হতেই সঙ্গে সঙ্গে হাসল।":"Đứa trẻ vừa như sắp khóc thì ngay lập tức cười.","বিস্তৃত এলাকাজুড়ে জরিপ প্রয়োজন।":"Cần khảo sát trên khu vực rộng.","খাবারটি যে খেতে পারি না তা নয়, তবে একটু ঝাল।":"Không phải là tôi không ăn được món đó, nhưng hơi cay.","গত বছরের তুলনায় ব্যবহারকারী বেড়েছে।":"So với năm ngoái, số người dùng đã tăng.","বসন্ত হলেও সকালে এখনো ঠান্ডা।":"Dù là mùa xuân, buổi sáng vẫn còn lạnh.","যান বা না যান, জানাবেন।":"Dù đi hay không đi, xin hãy thông báo.","এভাবে চললে দুর্ঘটনার আশঙ্কা আছে।":"Nếu cứ tiếp tục như thế này, có nguy cơ xảy ra tai nạn.","বাইরে বের হওয়া মাত্রই বৃষ্টি শুরু হলো।":"Ngay khi vừa ra ngoài, trời bắt đầu mưa.","বন্ধুর সঙ্গে দেখা হওয়ার সূত্রে আমার চিন্তা বদলেছে।":"Nhờ gặp gỡ bạn bè, suy nghĩ của tôi đã thay đổi.","না করলেও ভদ্রভাবে জানানো ভালো।":"Dù không làm, tốt hơn là nên thông báo một cách lịch sự.","টোকিওর তুলনায় এই শহরে ভাড়া কম।":"So với Tokyo, tiền thuê nhà ở thành phố này rẻ hơn.","এইমাত্র বেরিয়েছে, তাই ইতিমধ্যে পৌঁছে যাওয়ার কথা নয়।":"Mới vừa ra khỏi nhà, nên không đời nào đã đến nơi rồi.","বিষয়বস্তু যাচাই করার পরে স্বাক্ষর করুন।":"Hãy ký sau khi kiểm tra nội dung.","জাপানিতে অভ্যস্ত হওয়ার সঙ্গে কথা বলা আনন্দদায়ক হয়েছে।":"Cùng với việc quen với tiếng Nhật, việc nói chuyện đã trở nên vui vẻ.","কথা দিয়েছি বলে এখন আর না করা চলে না।":"Vì đã hứa nên bây giờ không thể không làm nữa.","এই প্রস্তাব সম্পর্কে আমার প্রশ্ন আছে।":"Tôi có câu hỏi về đề xuất này.","মতবিনিময় অনুষ্ঠানকে উপলক্ষ করে স্থানীয় কাজে যুক্ত হয়েছি।":"Lấy buổi giao lưu làm cơ hội, tôi đã tham gia vào công việc địa phương.","ট্রেন বন্ধ হওয়ায় ট্যাক্সি নেওয়া ছাড়া উপায় ছিল না।":"Vì tàu bị dừng, không còn cách nào ngoài việc đi taxi.","তিনি হাল না ছেড়ে অনুশীলন চালিয়েছেন।":"Anh ấy đã tiếp tục luyện tập mà không bỏ cuộc.","মনে হচ্ছিল যেন স্বপ্ন দেখছি।":"Tôi cảm thấy như thể đang mơ.","অতিথির চাহিদা অনুযায়ী কক্ষের ব্যবস্থা করব।":"Tôi sẽ sắp xếp phòng theo nhu cầu của khách.","প্রিয় বন্ধু বলেই সৎভাবে জানাতে চাই।":"Chính vì là bạn thân nên tôi muốn nói thật.","প্রতিদিন অনুশীলন করছে, নিশ্চয়ই দক্ষ হবে বলে মনে করি।":"Anh ấy luyện tập mỗi ngày, tôi tin chắc sẽ giỏi lên.","ব্যাখ্যা পড়েছি ঠিকই, কিন্তু ব্যবহারের পদ্ধতি এখনো বুঝিনি।":"Tôi đã đọc giải thích rồi, nhưng vẫn chưa hiểu cách sử dụng.","দোকানটি সারা বছর খোলা থাকে।":"Cửa hàng mở cửa suốt cả năm.","এত সহজ উপায়ে সব মনে রাখা যাবে, এমন নয় মোটেও।":"Không đời nào nhớ được tất cả bằng cách dễ dàng như vậy.","শুধু বিদেশি শিক্ষার্থী নয়, এলাকার মানুষও অংশ নিতে পারেন।":"Không chỉ học sinh nước ngoài, người dân địa phương cũng có thể tham gia.","আমার জানা মতে দোকানটি রবিবারও খোলা থাকে।":"Theo như tôi biết, cửa hàng mở cửa cả chủ nhật.","ব্যবস্থার পরিবর্তনের সঙ্গে প্রক্রিয়াও বদলেছে।":"Cùng với sự thay đổi của hệ thống, quy trình cũng đã thay đổi.","টাইফুনের কারণে ট্রেন বন্ধ হওয়ার আশঙ্কা আছে।":"Có nguy cơ tàu bị dừng do bão.","তিনি পথঘাট ভালো জানেন, নিশ্চয়ই স্থানীয় বলে মনে হয়।":"Anh ấy biết đường xá rất rõ, chắc chắn là người địa phương.","জ্বর আছে বলে বিশ্রাম না নিয়ে থাকা চলে না।":"Vì đang sốt nên không thể không nghỉ ngơi.","মতবিনিময় অনুষ্ঠানের মাধ্যমে নতুন বন্ধু হয়েছে।":"Thông qua buổi giao lưu, tôi đã có bạn mới.","সুস্থ থাকা পর্যন্ত কাজ চালিয়ে যেতে চাই।":"Tôi muốn tiếp tục làm việc chừng nào còn khỏe.","সফল হব কি না তা প্রস্তুতির ওপর নির্ভর করে।":"Việc có thành công hay không phụ thuộc vào sự chuẩn bị.","আকাশ অন্ধকার হলো মনে হতেই প্রবল বৃষ্টি নামল।":"Vừa thấy trời tối sầm thì mưa lớn đổ xuống.","বড় ভাই সকালে স্বচ্ছন্দ, এর বিপরীতে ছোট ভাই রাতে স্বচ্ছন্দ।":"Anh trai thoải mái vào buổi sáng, trái lại em trai thoải mái vào ban đêm.","ছোটবেলায় নদীতে প্রায়ই খেলতাম।":"Hồi nhỏ tôi thường chơi ở sông.","এটি বাস্তব অভিজ্ঞতার ভিত্তিতে লেখা প্রতিবেদন।":"Đây là báo cáo được viết dựa trên trải nghiệm thực tế.","বিদেশের জীবন আনন্দের, আবার পরিবারের জন্য মনও খারাপ হয়।":"Cuộc sống ở nước ngoài vui, nhưng cũng buồn vì nhớ gia đình.","অংশ নিন বা না নিন, উত্তর দিন।":"Dù tham gia hay không, xin hãy trả lời.","এই সমস্যা শুধু জাপানে নয়, অন্য দেশেও আছে।":"Vấn đề này không chỉ ở Nhật Bản, mà còn ở các nước khác.","কক্ষটি শান্ত বলার চেয়ে বরং নির্জন লাগে।":"Thay vì nói căn phòng yên tĩnh, thà nói nó vắng vẻ.","তিন দিনজুড়ে প্রশিক্ষণ অনুষ্ঠিত হয়েছে।":"Khóa đào tạo đã được tổ chức suốt ba ngày.","শহর একদিকে সুবিধাজনক, অন্যদিকে জীবনযাত্রার খরচ বেশি।":"Thành phố một mặt thuận tiện, mặt khác chi phí sinh hoạt cao.","কারণ না জেনে বিচার করা উচিত নয়।":"Không nên phán xét mà không biết lý do.","জাপানি হলেও সবাই যে কানজিতে দক্ষ তা নয়।":"Dù là người Nhật, không phải ai cũng giỏi kanji.","গ্রাহকসেবার ক্ষেত্রে অন্যের কথা শোনা জরুরি।":"Trong lĩnh vực dịch vụ khách hàng, việc lắng nghe người khác là quan trọng.","জাপানি বলতে পারলেও সম্মানসূচক ভাষায় আত্মবিশ্বাস নেই।":"Dù nói được tiếng Nhật, tôi vẫn không tự tin với kính ngữ.","কণ্ঠস্বর শোনা মাত্রই স্বস্তি পেলাম।":"Ngay khi nghe thấy giọng nói, tôi thấy nhẹ nhõm.","অভিজ্ঞতার সঙ্গে মানানসই কাজের দায়িত্ব দেব।":"Tôi sẽ giao trách nhiệm công việc phù hợp với kinh nghiệm.","আগে বন্ধুদের সঙ্গে প্রায়ই দীর্ঘ চিঠি লিখতাম।":"Ngày xưa tôi thường viết thư dài với bạn bè.","সুবিধা বেড়েছে ঠিকই, তবু সমস্যা রয়ে গেছে।":"Sự thuận tiện đã tăng thật, nhưng vấn đề vẫn còn.","জরিপের ফলকে ভিত্তি করে পরিকল্পনা করেছি।":"Tôi đã lập kế hoạch dựa trên kết quả khảo sát.","চালিয়ে যেতে পেরেছি ঠিক সহকর্মীরা পাশে ছিলেন বলেই।":"Tôi có thể tiếp tục được chính vì đồng nghiệp đã ở bên cạnh.","তিনি এমনভাবে কথা বললেন যেন কিছুই জানেন না।":"Anh ấy nói như thể không biết gì cả.","বন্ধুর জন্য চিন্তায় যোগাযোগ না করে থাকতে পারিনি।":"Vì lo cho bạn, tôi không thể không liên lạc.","দামি জিনিস সবসময় ভালো হবে এমন নয়।":"Đồ đắt tiền không phải lúc nào cũng tốt.","সহযোগিতা হলো একই লক্ষ্যে একসঙ্গে কাজ করা।":"Hợp tác là cùng làm việc hướng tới cùng một mục tiêu.","প্রবল বৃষ্টিতে পরিকল্পনা বদলানো ছাড়া উপায় নেই।":"Vì mưa lớn, không còn cách nào ngoài việc thay đổi kế hoạch.","সূচি ঠিক হওয়া মাত্র জানাব।":"Ngay khi lịch trình được ấn định, tôi sẽ thông báo.","বয়স নির্বিশেষে যে কেউ অংশ নিতে পারেন।":"Bất kể tuổi tác, ai cũng có thể tham gia.","কেইগো বলতে অন্যের প্রতি সম্মান প্রকাশের ভাষা বোঝায়।":"敬語 có nghĩa là ngôn ngữ bày tỏ sự tôn trọng đối với người khác.","জনসংখ্যা বৃদ্ধির সঙ্গে আবাসনের প্রয়োজন বেড়েছে।":"Cùng với sự gia tăng dân số, nhu cầu nhà ở đã tăng.","আমি শুধু মতামত জানিয়েছি।":"Tôi chỉ nêu ý kiến.","এবারের সাফল্য আপনাদের পরিশ্রমের ফলই।":"Thành công lần này chính là kết quả của sự nỗ lực của các bạn.","ঘটনাটি শুনলে না হেসে থাকতে পারি না।":"Nghe chuyện đó, tôi không thể không cười.","এটি কেবল একটি উদাহরণ।":"Đây chỉ là một ví dụ."},"lessons.explanation_bn":{"বক্তার দেখা দুটি ঘটনা খুব দ্রুত বদলে যায়। প্রথম অবস্থা বুঝে ওঠার আগেই পরের অবস্থা আসে—এই পরিবর্তনকে তুলে ধরে।":"Hai sự kiện người nói nhìn thấy thay đổi rất nhanh. Trước khi kịp hiểu trạng thái đầu tiên, trạng thái tiếp theo đã đến — nó nêu bật sự thay đổi này.","একটি ঘটনা বড় পরিবর্তন, নতুন অভ্যাস বা সম্পর্কের সূচনা করে। শুধু যেকোনো কারণ নয়, শুরু হওয়ার উপলক্ষকে জোর দেয়।":"Một sự kiện khởi đầu cho thay đổi lớn, thói quen mới hoặc mối quan hệ. Không phải bất kỳ nguyên nhân nào, nó nhấn mạnh cơ hội để bắt đầu.","কাজটি করতে সক্ষম হলেও দায়িত্ব, প্রতিশ্রুতি বা সামাজিক কারণে তা করা গ্রহণযোগ্য নয়। নেতিবাচক ক্রিয়ার সঙ্গে “না করে থাকা চলে না”, অর্থাৎ করতেই হবে।":"Dù có khả năng làm việc đó, nhưng vì trách nhiệm, lời hứa hoặc lý do xã hội mà việc làm đó không thể chấp nhận được. Với động từ phủ định là \"không thể không làm\", tức là buộc phải làm.","কোনো শব্দ বা ধারণাকে সামনে এনে তার অর্থ, সংজ্ঞা বা মূল বৈশিষ্ট্য ব্যাখ্যা করুন। প্রবন্ধ ও ব্যাখ্যামূলক লেখায় মানায়।":"Đưa một từ hoặc khái niệm ra phía trước và giải thích ý nghĩa, định nghĩa hoặc đặc điểm cốt lõi của nó. Phù hợp trong bài luận và văn giải thích.","পরিমাণ, ভূমিকা বা গুরুত্বকে সীমিত করে বোঝায়। বক্তা মনে করেন বিষয়টিকে তার চেয়ে বড় করে দেখা ঠিক নয়।":"Diễn tả việc giới hạn số lượng, vai trò hoặc tầm quan trọng. Người nói cho rằng không nên nhìn sự việc lớn hơn thế.","Vた-এর সঙ্গে প্রথম কাজ ভালোভাবে করে তারপর সিদ্ধান্ত বা কাজ করুন। Vる-এর সঙ্গে কোনো কাজের ক্ষেত্রে কী গুরুত্বপূর্ণ তা ব্যাখ্যা করুন।":"Với Vた, hãy làm tốt công việc đầu tiên rồi mới quyết định hoặc hành động. Với Vる, hãy giải thích điều gì quan trọng trong trường hợp làm một việc gì đó.","বাস্তবে ঠিক সেই অবস্থা না হলেও তেমন দেখায় বা অনুভূত হয়। কল্পনা ও উপমা তৈরি করতে ব্যবহার করুন।":"Dù thực tế không đúng trạng thái đó, nhưng trông hoặc cảm thấy như vậy. Hãy dùng để tạo tưởng tượng và phép ẩn dụ.","পরিচয় বা আসল কারণকে জোর দিয়ে নির্দিষ্ট করে। বক্তা দৃঢ়ভাবে বলেন, এটিই আসল ব্যাখ্যা। আনুষ্ঠানিক যুক্তি বা মূল্যায়নে উপযোগী।":"Nó nhấn mạnh và xác định danh tính hoặc nguyên nhân thực sự. Người nói khẳng định chắc chắn, đây chính là lời giải thích thực sự. Hữu ích trong lập luận hoặc đánh giá trang trọng.","চাহিদা, ক্ষমতা, পরিস্থিতি বা পরিবর্তনের সঙ্গে সামঞ্জস্য রেখে কাজ বা ব্যবস্থা বদলায়। সবার জন্য একই ব্যবস্থা বোঝায় না।":"Công việc hoặc cách sắp xếp thay đổi để phù hợp với nhu cầu, khả năng, tình huống hoặc sự thay đổi. Nó không có nghĩa là cùng một cách sắp xếp cho tất cả mọi người.","একই বিষয় বা পরিস্থিতির দুটি ভিন্ন দিক পাশাপাশি তুলে ধরে। ভালো-মন্দ, সুবিধা-অসুবিধা বা পরস্পর ভিন্ন প্রবণতা তুলনা করা যায়।":"Nêu bật hai khía cạnh khác nhau của cùng một sự việc hoặc tình huống bên cạnh nhau. Có thể so sánh tốt-xấu, lợi ích-bất lợi hoặc các xu hướng khác nhau.","একটি বড় পরিবর্তন বা ঘটনার সঙ্গে সম্পর্কিত আরেকটি পরিবর্তন ঘটে। সামাজিক প্রবণতা, নীতি ও সংখ্যা ব্যাখ্যায় উপযোগী।":"Một thay đổi khác xảy ra liên quan đến một thay đổi hoặc sự kiện lớn. Hữu ích khi giải thích xu hướng xã hội, chính sách và số liệu.","আগের অবস্থা বা শর্ত বজায় থাকা পর্যন্ত পরের কথা সত্য। 知[し]っている限[かぎ]り বলতে নিজের জানার সীমার মধ্যেও বোঝায়।":"Câu sau vẫn đúng chừng nào trạng thái hoặc điều kiện trước đó còn được duy trì. 知[し]っている限[かぎ]り cũng được hiểu là trong giới hạn những gì bạn biết.","কারণ বা পরিস্থিতি বিবেচনা করে বক্তা প্রবলভাবে সম্ভাবনা অস্বীকার করেন। এটি বক্তার দৃঢ় বিচার; বৈজ্ঞানিক নিশ্চয়তা দাবি নয়।":"Cân nhắc nguyên nhân hoặc tình huống, người nói phủ nhận mạnh mẽ khả năng. Đây là phán đoán chắc chắn của người nói; không phải tuyên bố chắc chắn khoa học.","নিয়ম, তথ্য, গবেষণা বা অভিজ্ঞতাকে সিদ্ধান্তের ভিত্তি হিসেবে ব্যবহার করা হয়। অনুমানের বদলে কী ভিত্তির ওপর কাজ হয়েছে তা বলুন।":"Quy tắc, dữ liệu, nghiên cứu hoặc kinh nghiệm được dùng làm cơ sở cho quyết định. Thay vì phỏng đoán, hãy nói công việc đã được thực hiện trên cơ sở nào.","কাজ বা অবস্থা দীর্ঘ সময়, বিস্তৃত এলাকা বা বহু বিষয়ের পরিসরজুড়ে চলেছে বোঝায়। পরিসরের বিস্তারকে গুরুত্ব দেয়।":"Diễn tả công việc hoặc trạng thái diễn ra trong thời gian dài, trên khu vực rộng hoặc trên phạm vi nhiều chủ đề. Nó nhấn mạnh sự rộng lớn của phạm vi.","অন্য বিকল্প না থাকায় অনিচ্ছা সত্ত্বেও কাজটি করতে হয়। বাইরের পরিস্থিতি বা বাস্তব সীমাবদ্ধতা বক্তাকে বাধ্য করে।":"Vì không có lựa chọn khác, dù không muốn vẫn phải làm việc đó. Tình huống bên ngoài hoặc giới hạn thực tế buộc người nói phải làm.","আবেগ বা প্রবল স্বাভাবিক তাড়নায় কাজটি না করে থাকা যায় না। নিজের অনুভূতি বা সহজে বোঝা প্রতিক্রিয়া প্রকাশে মানায়।":"Vì cảm xúc hoặc thôi thúc tự nhiên mạnh mẽ, không thể không làm việc đó. Nó phù hợp để diễn tả cảm xúc của bản thân hoặc phản ứng dễ hiểu.","একটি শ্রেণির বাইরে একই কথা আরও বিস্তৃত শ্রেণিতেও প্রযোজ্য হলে ব্যবহার করুন। পরে も বা 広[ひろ]く-এর মতো বিস্তারের ইঙ্গিত থাকতে পারে।":"Hãy dùng khi một điều không chỉ đúng với một nhóm mà còn đúng với một nhóm rộng hơn ngoài nhóm đó. Sau đó có thể có も hoặc những dấu hiệu mở rộng như 広[ひろ]く.","আগের তথ্য স্বীকার করেও সীমাবদ্ধতা, ব্যতিক্রম বা সতর্কতা জানান। প্রথম কথাটি মিথ্যা না বলে তাকে শর্তসাপেক্ষ করেন।":"Thừa nhận thông tin trước nhưng vẫn cho biết giới hạn, ngoại lệ hoặc sự thận trọng. Không nói điều đầu tiên là sai mà làm cho nó có điều kiện.","আগের কাজ ঘটার সঙ্গে সঙ্গেই অপ্রত্যাশিত পরিবর্তন বা ঘটনা ঘটে। পরের অংশে সাধারণত পরিকল্পিত নির্দেশ বা ইচ্ছা থাকে না।":"Ngay khi hành động trước xảy ra, một thay đổi hoặc sự kiện bất ngờ xảy ra. Ở phần sau thường không có chỉ thị hoặc ý định đã lên kế hoạch.","লক্ষণ, পরিস্থিতি বা জানা তথ্য থেকে বক্তা শক্ত অনুমান করেন। সরাসরি দেখা প্রমাণিত ঘটনা বলার বদলে নিজের বিচার প্রকাশ পায়।":"Từ dấu hiệu, tình huống hoặc thông tin đã biết, người nói suy đoán mạnh mẽ. Thay vì nói về sự kiện đã chứng minh được nhìn thấy trực tiếp, phán đoán của bản thân được bộc lộ.","ক্রিয়ার ます বাদ দেওয়া রূপে কোনো কাজ শেষ হলে দ্রুত পরের কাজ করার পরিকল্পনা জানায়। বিশেষ্যের সঙ্গে ফল নির্ভর করার অর্থ হয়।":"Ở dạng bỏ ます của động từ, nó cho biết kế hoạch làm nhanh công việc tiếp theo khi một công việc kết thúc. Với danh từ, nó có nghĩa kết quả phụ thuộc vào.","একটি পরিস্থিতি সত্য ধরে নিয়েও পরের মতামত বা সীমা বলুন। জোড়ায় AにしてもBにしても হলে উভয় ক্ষেত্রেই একই কথা প্রযোজ্য।":"Dù thừa nhận một tình huống là đúng, hãy nói ý kiến hoặc giới hạn tiếp theo. Khi dùng theo cặp AにしてもBにしても, cùng một điều áp dụng cho cả hai trường hợp.","প্রথম বর্ণনাটি পুরো ঠিক নয় মনে করে তার চেয়ে মানানসই দ্বিতীয় বর্ণনা দিন। বিরোধিতা নয়, আরও যথাযথ ভাষায় সংশোধন।":"Cho rằng mô tả đầu tiên chưa hoàn toàn đúng, hãy đưa ra mô tả thứ hai phù hợp hơn. Không phải phản đối, mà là sửa lại bằng ngôn ngữ thích hợp hơn.","একটি কারণকে বিশেষ গুরুত্ব দিয়ে ফলের সঙ্গে জুড়ে দেয়। কারণটি দুর্বল নয়; বক্তা সেটিকেই মূল প্রেরণা হিসেবে সামনে আনছেন।":"Nó đặc biệt nhấn mạnh một nguyên nhân và gắn nó với kết quả. Nguyên nhân không yếu; người nói đưa nó ra làm động lực chính.","একটি কাজ বা অবস্থা ঘটানো ছাড়া পরের কাজ ঘটে। লিখিত বা আনুষ্ঠানিক ভাষায় Vないで-এর কাছাকাছি অর্থ।":"Hành động tiếp theo xảy ra mà không gây ra một hành động hoặc trạng thái nào. Trong văn viết hoặc ngôn ngữ trang trọng, nó gần nghĩa với Vないで.","আগের তথ্য সত্য মেনে নিয়ে পরের অংশে তার প্রত্যাশিত ফল না হওয়ার কথা বলুন। লিখিত বা কিছুটা আনুষ্ঠানিক ব্যাখ্যায় বেশি মানায়।":"Thừa nhận thông tin trước là đúng, rồi ở phần sau nói kết quả kỳ vọng không xảy ra. Nó phù hợp hơn trong văn viết hoặc giải thích hơi trang trọng.","নেতিবাচক কথাটিকে পুরোপুরি মানতে চান না। সীমিত সক্ষমতা, আংশিক সত্য বা শর্তসাপেক্ষ সম্মতি প্রকাশ করেন।":"Không muốn thừa nhận hoàn toàn điều phủ định. Diễn tả khả năng hạn chế, sự thật một phần hoặc sự đồng ý có điều kiện.","একটি তুলনার মানদণ্ড নির্দিষ্ট করে পরের তথ্যের পার্থক্য দেখায়। হার, দাম, অতীত ও বর্তমান তুলনায় কাজে আসে।":"Nó xác định một tiêu chuẩn so sánh và cho thấy sự khác biệt của thông tin phía sau. Hữu ích khi so sánh tỷ lệ, giá cả, quá khứ và hiện tại.","একটি পরিবর্তন অগ্রসর হওয়ার সঙ্গে অন্য একটি অবস্থাও ধীরে বদলায়। বয়স, সময় বা অভিজ্ঞতার বৃদ্ধি বোঝাতে সুবিধাজনক।":"Cùng với một thay đổi tiến triển, một trạng thái khác cũng dần thay đổi. Thuận tiện để diễn tả sự tăng của tuổi tác, thời gian hoặc kinh nghiệm.","কাজ বা অনুভূতির লক্ষ্য বোঝায়। দুটি পক্ষের বিপরীত বৈশিষ্ট্য তুলনা করতেও ব্যবহার হয়; কোন ব্যবহার তা প্রসঙ্গ দেখে ধরুন।":"Diễn tả đối tượng của hành động hoặc cảm xúc. Nó cũng được dùng để so sánh đặc điểm đối lập của hai phía; hãy nắm bắt cách dùng nào qua ngữ cảnh.","কোনো অভিজ্ঞতা, মাধ্যম বা ব্যক্তির সাহায্যে ফল পাওয়া বোঝায়। সময়ের বিশেষ্যের সঙ্গে পুরো সময়জুড়েও বোঝাতে পারে।":"Diễn tả việc đạt kết quả nhờ một trải nghiệm, phương tiện hoặc sự giúp đỡ của ai đó. Với danh từ chỉ thời gian, nó cũng có thể diễn tả suốt cả khoảng thời gian.","আগের বিষয়টি যাই হোক, পরের ফল বা নিয়ম বদলায় না। বয়স, অভিজ্ঞতা, আবহাওয়া বা অংশগ্রহণের সিদ্ধান্তে ব্যবহার করা যায়।":"Dù sự việc trước là gì, kết quả hoặc quy tắc phía sau không thay đổi. Có thể dùng với tuổi tác, kinh nghiệm, thời tiết hoặc quyết định tham gia.","ভবিষ্যতে অনাকাঙ্ক্ষিত ফলের সম্ভাবনা বোঝায়। সংবাদ, সতর্কতা ও আনুষ্ঠানিক ব্যাখ্যায় ব্যবহার হয়।":"Diễn tả khả năng xảy ra kết quả không mong muốn trong tương lai. Được dùng trong tin tức, cảnh báo và giải thích trang trọng.","একটি সাধারণ অনুমান সবার ক্ষেত্রে ঠিক নয়—এই আংশিক নাকচ প্রকাশ করে। কিছু ক্ষেত্রে সত্য হতে পারে, কিন্তু নিশ্চিত নয়।":"Nó diễn tả sự phủ định một phần — một phỏng đoán chung không đúng với mọi người. Có thể đúng trong một số trường hợp, nhưng không chắc chắn.","আগেকার অভ্যাস বা বারবার ঘটত এমন অভিজ্ঞতা স্মরণ করে বলুন। এতে স্মৃতিকাতর ভাব থাকতে পারে।":"Hãy nói bằng cách hồi tưởng thói quen xưa hoặc trải nghiệm từng xảy ra nhiều lần. Trong đó có thể có sắc thái hoài niệm."},"lessons.forms":{"必[かなら]ずしも + ইতিবাচক ধারণা + নেতিবাচক predicate":"必[かなら]ずしも + ý khẳng định + vị ngữ phủ định","Vない・い-বিশেষণくない + ことはない / N・な-বিশেষণでない + ことはない":"Vない・い-tính từくない + ことはない / N・な-tính từでない + ことはない","Vない-এর ない বাদ + ずにはいられない（する → せずにはいられない）":"Bỏ ない của Vない + ずにはいられない (する → せずにはいられない)","Plain form + からこそ（N・な-বিশেষণ: だ + からこそ）":"Plain form + からこそ (N・な-tính từ: だ + からこそ)","V・い-বিশেষণ plain + 一方[いっぽう]で / な-বিশেষণ + な一方[いっぽう]で / N + である一方[いっぽう]で":"V・tính từ い dạng thông thường + 一方[いっぽう]で / tính từ な + な一方[いっぽう]で / N + である一方[いっぽう]で","সময়・এলাকা・পরিসর N + にわたって / N + にわたる + N":"Thời gian・khu vực・phạm vi N + にわたって / N + にわたる + N","Vる・Vている・Vない + 限[かぎ]り / N・な-বিশেষণである + 限[かぎ]り":"Vる・Vている・Vない + 限[かぎ]り / N・tính từ なである + 限[かぎ]り","N + とは + সংজ্ঞা・ব্যাখ্যা":"N + とは + định nghĩa・giải thích","Plain form + とはいえ（N・な-বিশেষণে だ-ও বাদ যায়）":"Plain form + とはいえ (với N・な-tính từ, だ cũng bị lược bỏ)","Vます-stem + 次第[しだい]（সঙ্গে সঙ্গে） / N + 次第[しだい]だ（নির্ভর）":"thân Vます + 次第[しだい]（ngay khi） / N + 次第[しだい]だ（phụ thuộc vào）","Vない-এর ない বাদ + ざるを得[え]ない（する → せざるを得[え]ない）":"Bỏ ない của Vない + ざるを得[え]ない（する → せざるを得[え]ない）","V・い-বিশেষণ plain + かのようだ / N・な-বিশেষণ + であるかのようだ":"Plain của V・い-tính từ + かのようだ / N・な-tính từ + であるかのようだ","V・い-বিশেষণ plain + に違[ちが]いない / N・な-বিশেষণ + に違[ちが]いない":"V・tính từ い dạng thông thường + に違[ちが]いない / N・tính từ な + に違[ちが]いない","V・い-বিশেষণ plain + ものの / な-বিশেষণ + なものの / N + であるものの":"Plain của V・い-tính từ + ものの / な-tính từ + なものの / N + であるものの","Vた + ものだ（অতীতের স্মৃতি）":"Vた + ものだ (ký ức quá khứ)","V・い-বিশেষণ plain + わけがない / な-বিশেষণ + なわけがない / N + のわけがない":"Plain của V・い-tính từ + わけがない / な-tính từ + なわけがない / N + のわけがない","Vた + 上[うえ]で（ক্রম） / Vる・Nの + 上[うえ]で（ক্ষেত্র）":"Vた + 上[うえ]で（trình tự） / Vる・Nの + 上[うえ]で（lĩnh vực）","N + に対[たい]して / N + に対[たい]する + N（লক্ষ্য）":"N + に対[たい]して / N + に対[たい]する + N（đối tượng）"},"lessons.meaning_bn":{"… করা মাত্রই হঠাৎ":"Ngay khi vừa làm … thì đột nhiên","একদিকে …, অন্যদিকে …":"Một mặt …, mặt khác …","…এর তুলনায়":"So với …","যদিও …, তবু …":"Mặc dù …, nhưng …","…কে সূচনা বা উপলক্ষ করে":"Lấy … làm khởi đầu hoặc cơ hội","…অনুযায়ী মানিয়ে":"Điều chỉnh theo …","…জুড়ে বিস্তৃতভাবে":"Trải rộng khắp …","… বলতে কী বোঝায়":"… có nghĩa là gì","… না করেই":"Mà không làm …","… বলার চেয়ে বরং …":"Thay vì nói …, thà nói …","একেবারে … নয়, তা নয় / কিছুটা সম্ভব":"Không phải là hoàn toàn không … / có thể một phần","… নির্বিশেষে":"Bất kể …","…কে ভিত্তি করে":"Dựa trên …","… হলেই সঙ্গে সঙ্গে / …এর ওপর নির্ভর":"Ngay khi … xong / phụ thuộc vào …","… না করে উপায় নেই":"Buộc phải làm …, không còn cách nào khác","…এর প্রতি / এর বিপরীতে":"Đối với … / trái lại","নিশ্চয়ই … হবে, আমার দৃঢ় ধারণা":"Chắc chắn sẽ …, tôi tin chắc","… হওয়ার কোনো কথাই নয়":"Không đời nào …","ঠিক … বলেই":"Chính vì …","… হলো মনে হতেই আবার …":"Vừa nghĩ là … thì lại …","…এর সঙ্গে সংশ্লিষ্ট পরিবর্তনে":"Trong thay đổi liên quan đến …","এমন বলা গেলেও":"Dù có thể nói như vậy","… করার পরে / … করার ক্ষেত্রে":"Sau khi làm … / trong trường hợp làm …","যতক্ষণ … শর্ত বজায় থাকে":"Chừng nào điều kiện … còn duy trì","একসময় প্রায়ই … করতাম":"Ngày xưa thường hay …","…এর মাধ্যমে / …জুড়ে":"Thông qua … / suốt …","… হলেও / এমনকি … ক্ষেত্রেও":"Dù … / ngay cả trong trường hợp …","যত …, তত পরিবর্তন":"Càng …, càng thay đổi","… না করে থাকতে পারি না":"Không thể không làm …","পরিস্থিতিগত কারণে … করা চলে না":"Vì lý do tình huống nên không thể làm …","অন্য কিছু নয়, ঠিক …ই":"Không gì khác, chính là …","মাত্র …, এর বেশি নয়":"Chỉ …, không hơn","শুধু … নয়, অন্যদের ক্ষেত্রেও":"Không chỉ …, mà cả với những người khác","খারাপ কিছু ঘটার আশঙ্কা আছে":"Có nguy cơ điều xấu xảy ra","সবসময় বা সবার ক্ষেত্রে … নয়":"Không phải lúc nào hoặc với mọi người cũng …","মনে হয় যেন …":"Có vẻ như thể …"},"lessons.quiz.explanation_bn":{"必[かなら]ずしも + とは限[かぎ]らない সাধারণ অনুমানকে আংশিক নাকচ করে।":"必[かなら]ずしも + とは限[かぎ]らない phủ định một phần một suy đoán thông thường.","দুটি নেতিবাচক অংশ সীমিত বা শর্তসাপেক্ষ সক্ষমতা প্রকাশ করে।":"Hai phần phủ định thể hiện khả năng có giới hạn hoặc phụ thuộc vào điều kiện.","সংখ্যা কম বা সীমিত হিসেবে দেখাতে にすぎない।":"Dùng にすぎない để chỉ một số lượng là ít hoặc có giới hạn.","する-এর ব্যতিক্রমী ず-রূপ せず।":"Dạng ず ngoại lệ của する là せず.","বিশ্রাম না নিয়ে কাজ চালানোর অর্থে dictionary form + ことなく।":"Dùng dạng từ điển + ことなく với nghĩa tiếp tục làm việc mà không nghỉ ngơi.","ব্যবহারকারী বাড়ার সঙ্গে সম্পর্ক রেখে সেবা বেড়েছে।":"Dịch vụ đã tăng lên cùng với số người dùng tăng lên.","ব্যর্থতা থেকে নতুন পড়ার পদ্ধতির শুরু হয়েছে।":"Từ thất bại, một phương pháp học mới đã bắt đầu.","অভিজ্ঞতা থাকুক বা না থাকুক আবেদন করা যাবে, তাই にかかわらず।":"Dù bạn có kinh nghiệm hay không, bạn vẫn có thể nộp đơn, vì vậy dùng にかかわらず.","প্রথমে আলোচনা শেষ করে পরে সিদ্ধান্ত, তাই Vた + 上[うえ]で।":"Trước tiên thảo luận xong rồi mới quyết định, vì vậy dùng Vた + 上[うえ]で.","নদীর পানি উপচে পড়া অনাকাঙ্ক্ষিত সম্ভাবনা, তাই おそれがある।":"Nước sông tràn bờ là một khả năng không mong muốn, vì vậy dùng おそれがある.","স্তরের সঙ্গে মিলিয়ে বই বদলায়, তাই に応[おう]じて।":"Sách thay đổi cho phù hợp với trình độ, vì vậy dùng に応[おう]じて.","উপভাষা কী, তার সংজ্ঞা দেওয়া হচ্ছে।":"Đang đưa ra định nghĩa phương ngữ là gì.","বুকিং করার পরও প্রত্যাশিতভাবে যাওয়া হয়নি; ものの এই অমিল দেখায়।":"Dù đã đặt chỗ nhưng cuối cùng lại không đi như dự kiến; ものの thể hiện sự không khớp này.","ব্যর্থ হওয়াটিকেই প্রস্তুতির গুরুত্ব বোঝার বিশেষ কারণ করা হয়েছে।":"Chính việc thất bại đã được coi là lý do đặc biệt để hiểu tầm quan trọng của việc chuẩn bị.","জানালা খোলার সঙ্গে সঙ্গে অপ্রত্যাশিত বাতাস—Vた + とたん।":"Ngay khi mở cửa sổ thì có một cơn gió bất ngờ — Vた + とたん.","পরিশ্রমের ফলই আসল পরিচয়—এই জোরালো মূল্যায়নে にほかならない।":"Kết quả của sự nỗ lực mới chính là bản chất thật — dùng にほかならない cho đánh giá nhấn mạnh này.","する ব্যতিক্রমীভাবে せざるを得[え]ない হয়।":"する trở thành せざるを得[え]ない một cách ngoại lệ.","কাজ ছিল সংস্কৃতি শেখার মাধ্যম, তাই を通[とお]して।":"Công việc là phương tiện để học văn hóa, vì vậy dùng を通[とお]して.","শিক্ষার্থী ছাড়াও শিক্ষক অংশ নেন; সীমা বিস্তৃত হচ্ছে, তাই に限[かぎ]らず।":"Không chỉ học sinh mà giáo viên cũng tham gia; phạm vi đang được mở rộng, vì vậy dùng に限[かぎ]らず.","終[お]わります থেকে ます বাদ দিয়ে 次第[しだい]; কাজ শেষ হলেই পরিকল্পিত যোগাযোগ।":"Từ 終[お]わります, bỏ ます và thêm 次第[しだい]; ngay khi công việc kết thúc sẽ liên lạc như đã lên kế hoạch.","সস্তা হওয়া মেনেও কেনার সীমা দেখাচ্ছে।":"Dù thừa nhận là rẻ, câu này cũng chỉ ra giới hạn trong việc mua.","ব্যাখ্যার ভিত্তি হবে ঘটনা বা তথ্য, তাই に基[もと]づいて।":"Việc giải thích sẽ dựa trên sự việc hoặc thông tin, vì vậy dùng に基[もと]づいて.","ফিরে আসার পরপরই আবার বের হওয়া—দ্রুত অবস্থা বদলাচ্ছে।":"Ngay sau khi trở về lại ra ngoài ngay — tình huống thay đổi nhanh chóng.","কথা বলার ধরনকে উপমা দিয়ে বর্ণনা করায় かのように।":"Vì cách nói được mô tả bằng phép so sánh nên dùng かのように.","関心[かんしん] বিশেষ্যকে বর্ণনা করছে, তাই に対[たい]する।":"関心[かんしん] đang bổ nghĩa cho một danh từ, vì vậy dùng に対[たい]する.","শান্ত হওয়া ও যাতায়াত অসুবিধা—দুটি ভিন্ন দিক, তাই 一方[いっぽう]で।":"Yên tĩnh và giao thông bất tiện — hai mặt khác nhau, vì vậy dùng 一方[いっぽう]で.","অভিজ্ঞতা বাড়ার সঙ্গে আত্মবিশ্বাস বাড়ছে—পরিবর্তনের সহগতি।":"Khi kinh nghiệm tăng lên, sự tự tin cũng tăng lên — sự thay đổi đi cùng nhau.","রাগের বর্ণনা বদলে বিপাকে পড়াকে বেশি যথাযথ বলা হচ্ছে।":"Thay vì mô tả là tức giận, người ta nói rằng mô tả là đang gặp khó khăn thì phù hợp hơn.","এখানে বসবাসের শর্ত বজায় থাকাকালীন নিয়ম মানতে হবে।":"Ở đây, bạn phải tuân thủ quy tắc chừng nào điều kiện sinh sống ở đây còn duy trì.","ব্যস্ততা মেনেও যোগাযোগের প্রয়োজন বোঝানো হয়েছে।":"Dù thừa nhận là bận rộn, câu này cũng cho thấy sự cần thiết phải liên lạc.","দুই সপ্তাহজুড়ে সাক্ষাৎকার নেওয়ার বিস্তার বোঝাচ্ছে।":"Câu này thể hiện việc phỏng vấn trải dài trong suốt hai tuần.","আলো জ্বলছে দেখে কেউ আছেন বলে দৃঢ় অনুমান করা হয়েছে।":"Thấy đèn sáng, người ta suy đoán chắc chắn rằng có ai đó ở đó.","এটি দেরি করার সামর্থ্যের প্রশ্ন নয়; গুরুত্বপূর্ণ সভায় দেরি করা চলে না।":"Đây không phải là câu hỏi về khả năng đến muộn được hay không; bạn không được đến muộn trong một cuộc họp quan trọng.","গত মাস হচ্ছে তুলনার ভিত্তিকাল, তাই に比[くら]べて।":"Tháng trước là thời điểm cơ sở để so sánh, vì vậy dùng に比[くら]べて.","অতীতের পুনরাবৃত্ত অভ্যাস স্মরণ করতে Vた + ものだ।":"Dùng Vた + ものだ để nhớ lại một thói quen lặp đi lặp lại trong quá khứ.","কোনোভাবেই বলার কথা নয়—দৃঢ় অস্বীকারে わけがない।":"Không đời nào có chuyện nói như vậy — dùng わけがない để phủ định mạnh mẽ."},"lessons.quiz.options":{"পড়তে একেবারে পারি না, তা নয়":"Không phải là hoàn toàn không đọc được","একেবারেই পড়তে পারি না":"Hoàn toàn không đọc được","অবশ্যই নিখুঁতভাবে পড়ি":"Chắc chắn đọc một cách hoàn hảo"},"lessons.quiz.prompt":{"দৃঢ় অস্বীকার:「彼[かれ]がそんなことを言[い]う（　）。」":"Phủ định mạnh mẽ:「彼[かれ]がそんなことを言[い]う（　）。」","「読[よ]めないことはない。」—কোন অর্থ?":"「読[よ]めないことはない。」— có nghĩa là gì?","「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」—সময়ের বিস্তার।":"「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」— khoảng thời gian kéo dài.","する-এর সঠিক রূপ:「心配[しんぱい]（　）にはいられない。」":"Dạng đúng của する:「心配[しんぱい]（　）にはいられない。」","「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」—পরিবর্তনের সূচনা।":"「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」— điểm bắt đầu của sự thay đổi.","「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」—মাধ্যম।":"「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」— phương tiện.","「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」—দৃঢ় মূল্যায়ন।":"「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」— đánh giá mạnh mẽ.","「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」—তুলনা।":"「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」— so sánh.","দৃঢ় অনুমান:「電気[でんき]がついている。誰[だれ]かいる（　）。」":"Suy đoán chắc chắn:「電気[でんき]がついている。誰[だれ]かいる（　）。」","「すべて分[わ]かっている（　）話[はな]す。」—যেন সব জানে।":"「すべて分[わ]かっている（　）話[はな]す。」— như thể biết mọi thứ.","「大雨[おおあめ]で川[かわ]があふれる（　）。」—অনাকাঙ্ক্ষিত ঝুঁকি।":"「大雨[おおあめ]で川[かわ]があふれる（　）。」— rủi ro không mong muốn.","「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」—শর্ত মেনে সীমা।":"「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」— thừa nhận điều kiện nhưng chỉ ra giới hạn.","「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」—লক্ষ্যবিষয়।":"「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」— chủ đề mục tiêu.","শেষ হলেই জানাব:「終[お]わり（　）、連絡[れんらく]します。」":"Ngay khi kết thúc sẽ thông báo:「終[お]わり（　）、連絡[れんらく]します。」","「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」—ক্রমে পরিবর্তন।":"「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」— thay đổi dần dần.","「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」—কারণে জোর।":"「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」— nhấn mạnh nguyên nhân.","「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」—দুটি দিক।":"「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」— hai mặt.","「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」—না করে।":"「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」— mà không làm.","আগে আলোচনা, তারপর সিদ্ধান্ত:「相談[そうだん]（　）上[うえ]で、決[き]めます。」":"Thảo luận trước, rồi quyết định sau:「相談[そうだん]（　）上[うえ]で、決[き]めます。」","「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」—শিক্ষার্থীর বাইরেও প্রযোজ্য।":"「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」— áp dụng cả ngoài học sinh.","「帰[かえ]ってきた（　）、また出[で]かけた。」—দ্রুত পালাবদল।":"「帰[かえ]ってきた（　）、また出[で]かけた。」— thay đổi nhanh chóng.","する-এর সঠিক রূপ:「中止[ちゅうし]（　）を得[え]ない。」":"Dạng đúng của する:「中止[ちゅうし]（　）を得[え]ない。」","「レベル（　）、教材[きょうざい]を変[か]えます。」—মানিয়ে নেওয়া।":"「レベル（　）、教材[きょうざい]を変[か]えます。」— điều chỉnh cho phù hợp.","সংজ্ঞা:「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」":"Định nghĩa:「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」","「事実[じじつ]（　）、説明[せつめい]してください。」—ভিত্তি।":"「事実[じじつ]（　）、説明[せつめい]してください。」— cơ sở.","「怒[おこ]っている（　）、困[こま]っているようだ。」—আরও যথাযথ বর্ণনা।":"「怒[おこ]っている（　）、困[こま]っているようだ。」— mô tả phù hợp hơn.","পুরোনো অভ্যাস:「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」":"Thói quen cũ:「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」","「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」—দায়িত্ববোধ।":"「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」— ý thức trách nhiệm.","「参加者[さんかしゃ]は十人[じゅうにん]（　）。」—মাত্র দশজন।":"「参加者[さんかしゃ]は十人[じゅうにん]（　）。」— chỉ mười người."},"lessons.tip_bn":{"する-এর রূপ せざる; しざる নয়। নিজের আগ্রহে পছন্দ করা কাজের জন্য নয়।":"Dạng của する là せざる; không phải しざる. Không dùng cho công việc được chọn vì sở thích của bản thân.","わけではない = পুরোপুরি এমন নয়; わけがない = কোনোভাবেই এমন হওয়ার কথা নয়।":"わけではない = không hoàn toàn như vậy; わけがない = không đời nào như vậy.","এই পাঠে সংজ্ঞার ব্যবহার; とは思[おも]わなかった-তে বিস্ময়ের ব্যবহার আলাদা।":"Trong bài này dùng để định nghĩa; cách dùng thể hiện sự ngạc nhiên trong とは思[おも]わなかった là khác.","কারণ জানাতে からにほかならない; শুধু বিশেষ্যের পরিচয় জোর দিতে にほかならない।":"Để cho biết nguyên nhân dùng からにほかならない; để chỉ nhấn mạnh danh tính của danh từ dùng にほかならない.","অভিজ্ঞতার মাধ্যমে শেখা এবং সারা বছরজুড়ে—এই দুই ব্যবহার প্রসঙ্গ দেখে আলাদা করুন।":"Học qua trải nghiệm và suốt cả năm — hãy phân biệt hai cách dùng này theo ngữ cảnh.","যদিও গ্রীষ্ম, তবু পাহাড়ে ঠান্ডা—এই ধরনের স্বীকারের পর সীমা দেখায়।":"Dù là mùa hè, nhưng trên núi vẫn lạnh — sau sự thừa nhận kiểu này, nó cho thấy giới hạn.","だけでなく-এর মতো বিস্তার বোঝায়; “এই সময়ের মধ্যে সীমাবদ্ধ” অর্থের に限[かぎ]り আলাদা।":"Nó thể hiện sự mở rộng giống như だけでなく; に限[かぎ]り với nghĩa “giới hạn trong khoảng thời gian này” là khác.","জোরপূর্বক বাইরের বাধ্যবাধকতা নয়; হাসি, চিন্তা, কান্নার মতো ভেতরের তাড়না প্রধান।":"Không phải là nghĩa vụ bắt buộc từ bên ngoài; thôi thúc bên trong như cười, lo lắng, khóc là chính.","に応[おう]じて শর্ত অনুযায়ী বদলায়; にかかわらず শর্তে বদলায় না।":"に応[おう]じて thay đổi tùy theo điều kiện; にかかわらず không thay đổi bất kể điều kiện.","遅[おく]れるにしても মানে দেরি হলেও; দেরি করার অনুমতি দেওয়া নয়।":"遅[おく]れるにしても có nghĩa là dù có đến muộn; nó không có nghĩa là cho phép đến muộn.","দুটি ঘটনা শুধু পাশাপাশি নয়; সম্পর্কিত পরিবর্তন দেখাতে হবে।":"Hai sự kiện không chỉ đứng cạnh nhau; phải cho thấy thay đổi có liên quan.","食[た]べられないことはない = খাওয়া একেবারে অসম্ভব নয়; স্বচ্ছন্দে খেতে পারি এমন জোর নেই।":"食[た]べられないことはない = không phải là hoàn toàn không thể ăn; nó không nhấn mạnh rằng bạn có thể ăn một cách thoải mái.","নিয়মিত “এর পরে” বলার জন্য てから যথেষ্ট; とたん হঠাৎ ঘটার অনুভূতি দেয়।":"Để nói \"sau đó\" thông thường, てから là đủ; とたん cho cảm giác xảy ra đột ngột.","কিসের সঙ্গে তুলনা করছেন তা পরিষ্কার রাখুন; শুধু সংখ্যা বললেই তুলনা সম্পূর্ণ হয় না।":"Hãy giữ rõ bạn đang so sánh với cái gì; chỉ nói số liệu thì so sánh chưa hoàn chỉnh.","পরের বিশেষ্যকে বর্ণনা করলে かのようなN; ক্রিয়াকে বর্ণনা করলে かのようにV।":"Khi bổ nghĩa cho danh từ phía sau dùng かのようなN; khi bổ nghĩa cho động từ dùng かのようにV.","রূপ বদলালে অর্থ বদলায়: 確認[かくにん]した上[うえ]で = যাচাইয়ের পরে; 働[はたら]く上[うえ]で = কাজ করার ক্ষেত্রে।":"Ý nghĩa thay đổi khi hình thức thay đổi: 確認[かくにん]した上[うえ]で = sau khi kiểm tra; 働[はたら]く上[うえ]で = trong khi làm việc.","মাত্র তিনজন = 三人[さんにん]にすぎない; প্রায় তিনজন = 三人[さんにん]ぐらい—অর্থ আলাদা।":"Chỉ ba người = 三人[さんにん]にすぎない; khoảng ba người = 三人[さんにん]ぐらい — ý nghĩa khác nhau.","আগের ঘটনাটি পরের পরিবর্তনের শুরু; দৈনন্দিন ছোট কারণেও সবসময় ব্যবহার করবেন না।":"Sự kiện trước là khởi đầu của thay đổi sau; đừng lúc nào cũng dùng cho những nguyên nhân nhỏ hằng ngày.","Vる + 一方[いっぽう]だ শুধু পরিবর্তন এক দিকেই এগোনো বোঝাতে পারে; এই পাঠে শেষে で আছে।":"Vる + 一方[いっぽう]だ cũng có thể chỉ sự thay đổi chỉ tiến triển theo một hướng; trong bài này có で ở cuối.","বাক্যের পরের অংশে আগের শর্ত অনুযায়ী মানিয়ে নেওয়ার সম্পর্ক খুঁজুন।":"Ở phần sau của câu, hãy tìm mối quan hệ điều chỉnh theo điều kiện trước đó.","から সাধারণ কারণ, からこそ সেই কারণকে জোর দেয়। পরে ইতিবাচক উপদেশ বা মূল্যায়ন প্রায়ই আসে।":"から là nguyên nhân thông thường, からこそ nhấn mạnh nguyên nhân đó. Phía sau thường có lời khuyên hoặc đánh giá tích cực.","নিশ্চয়তা অনুভব করলেও এটি অনুমান; হুবহু “প্রমাণিত সত্য” নয়।":"Dù cảm thấy chắc chắn, đây vẫn là suy đoán; không đúng là \"sự thật đã chứng minh\".","সাধারণ “ভাবছি” অর্থ নয়। দ্রুত পালাবদল; নিজের ইচ্ছাকৃত ধারাবাহিক কাজ বোঝাতে কম মানায়।":"Không phải nghĩa \"đang nghĩ\" thông thường. Sự thay đổi nhanh chóng; ít phù hợp để diễn tả chuỗi hành động có chủ ý của bản thân.","সরাসরি dictionary form লাগে: 休[やす]むことなく; 休[やす]まないことなく লিখবেন না।":"Trực tiếp dùng dạng từ điển: 休[やす]むことなく; đừng viết 休[やす]まないことなく.","এই পাঠে শর্তের ব্যবহার। 時間[じかん]の限[かぎ]り মানে সময়ের শেষ সীমা পর্যন্ত—প্রসঙ্গ আলাদা।":"Trong bài này dùng cho điều kiện. 時間[じかん]の限[かぎ]り có nghĩa là cho đến giới hạn cuối cùng của thời gian — ngữ cảnh khác.","পরের অংশে পরিবর্তন দিন; একটি নির্দিষ্ট মুহূর্তের সিদ্ধান্ত বা সরাসরি আদেশ মানায় না।":"Ở phần sau hãy đưa thay đổi; quyết định tại một thời điểm cụ thể hoặc mệnh lệnh trực tiếp không phù hợp.","終[お]わり次第[しだい] = শেষ হলেই; 天気[てんき]次第[しだい] = আবহাওয়ার ওপর নির্ভর।":"終[お]わり次第[しだい] = ngay khi kết thúc; 天気[てんき]次第[しだい] = phụ thuộc vào thời tiết.","ভালো ফলের সম্ভাবনায় সাধারণত使[つか]わない; 危険[きけん] বা ক্ষতির পূর্বাভাসে মানায়।":"Đối với khả năng có kết quả tốt, thường 使[つか]わない; nó phù hợp khi dự báo 危険[きけん] hoặc thiệt hại.","একবারের সাম্প্রতিক ঘটনা নয়। ものだ-এর সাধারণ সত্য বা উপদেশের ব্যবহার থেকে এটি আলাদা।":"Không phải sự kiện gần đây chỉ xảy ra một lần. Nó khác với cách dùng ものだ cho chân lý chung hoặc lời khuyên.","সরাসরি অক্ষমতা できない থেকে আলাদা। 休[やす]まないわけにはいかない মানে বিশ্রাম নিতেই হবে।":"Khác với sự bất lực trực tiếp できない. 休[やす]まないわけにはいかない có nghĩa là nhất định phải nghỉ ngơi.","একটি নির্দিষ্ট মুহূর্তের জন্য নয়। 一時間[いちじかん]にわたる説明[せつめい] মানে এক ঘণ্টাজুড়ে ব্যাখ্যা।":"Không dùng cho một khoảnh khắc cụ thể duy nhất. 一時間[いちじかん]にわたる説明[せつめい] có nghĩa là phần giải thích kéo dài suốt một giờ.","দুটি বিকল্পের মধ্যে দ্বিতীয়টি বেশি সঠিক—এই দিকটি খেয়াল রাখুন।":"Trong hai lựa chọn, cái thứ hai đúng hơn — hãy chú ý khía cạnh này.","পুরোপুরি অসম্ভব অর্থ নয়। 必[かなら]ずしも-এর সঙ্গে শেষে নেতিবাচক অর্থ রাখুন।":"Không có nghĩa là hoàn toàn không thể. Hãy giữ ý phủ định ở cuối cùng với 必[かなら]ずしも.","বিশেষ্যের আগে に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん]।":"Trước danh từ dùng に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん].","単[たん]に “অনুযায়ী” নয়; সিদ্ধান্তের ভিত্তির সঙ্গে দৃঢ় সম্পর্ক আছে।":"Không chỉ 単[たん]に có nghĩa là “theo”; nó có mối quan hệ chặt chẽ với cơ sở của một quyết định.","ものの-এর পরে বাস্তব ফল বা অবস্থা দিন। শুধু দুটি কাজের ক্রম বোঝাতে ব্যবহার করবেন না।":"Sau ものの, hãy đưa kết quả hoặc trạng thái thực tế. Đừng dùng chỉ để diễn tả thứ tự của hai hành động."},"scope_bn":{"QUARTET II-এর ৭–১২ অধ্যায়ের থিম অনুসরণে নির্বাচিত ৩৬টি গ্রামারের নিজস্ব সহায়ক অনুশীলন। এটি মূল বইয়ের সম্পূর্ণ গ্রামার সূচি নয়।":"Bài luyện hỗ trợ riêng cho 36 ngữ pháp được chọn theo chủ đề các chương 7–12 của QUARTET II. Đây không phải mục lục ngữ pháp đầy đủ của sách gốc."},"study.dialogue":{"ঠিক বলেছেন। এখনই যোগাযোগ করে দেখব।":"Bạn nói đúng. Tôi sẽ liên lạc ngay.","হ্যাঁ। যাচাই করার পরে সিদ্ধান্ত নিই।":"Vâng. Sau khi kiểm tra, chúng ta hãy quyết định.","নির্দেশনার কাগজ বাড়ালে কেমন হয়?":"Tăng thêm giấy hướng dẫn thì sao?","আজ আপনার বাসায় আসতে পারি?":"Hôm nay tôi có thể đến nhà bạn không?","কিছু হয়েছে?":"Có chuyện gì vậy?","গ্রাহকসেবার ক্ষেত্রে কোন বিষয়কে গুরুত্ব দেন?":"Trong lĩnh vực dịch vụ khách hàng, bạn coi trọng điều gì?","আচ্ছা। তাহলে সুবিধামতো একটি দিন জানাবেন?":"Vậy à. Thế bạn cho tôi biết một ngày thuận tiện nhé?","আগামীকাল একটু সাহায্য করবেন?":"Ngày mai bạn giúp tôi một chút được không?","আগে ব্যবহারকারীদের জিজ্ঞেস করে দেখব?":"Trước tiên hỏi người dùng xem sao?","এই গ্রাফ থেকে কী বোঝা যায়?":"Từ biểu đồ này có thể hiểu được gì?","রবিবার হলে পারব।":"Nếu là chủ nhật thì tôi có thể.","এটিও একটি উপায়, তবে ভাষা বদলানোর প্রয়োজনও আছে বলে মনে করি।":"Đây cũng là một cách, nhưng tôi nghĩ cũng cần thay đổi ngôn ngữ.","তাহলে রবিবার হলে কেমন হয়?":"Vậy chủ nhật thì sao?","প্রথমে গ্রাহকের চাহিদা নিশ্চিত করি।":"Trước tiên tôi xác nhận nhu cầu của khách hàng.","স্টেশনে খোঁজ নিয়ে দেখলে কেমন হয়?":"Hay là bạn hỏi ở nhà ga xem sao?","কিছু কথা জিজ্ঞেস করতে পারি?":"Tôi có thể hỏi vài điều không?","একটি গুরুত্বপূর্ণ খাতা হারিয়ে ফেলেছি।":"Tôi đã làm mất một cuốn sổ quan trọng.","আগামীকাল কাজ আছে বলে পারব না।":"Ngày mai tôi có việc nên không thể.","দুঃখিত, আজ আমার অন্য কাজ আছে।":"Xin lỗi, hôm nay tôi có việc khác.","অন্য স্কুলেও কি একই রকম হবে?":"Ở trường khác cũng sẽ giống vậy sao?","ট্রেন ব্যবহারকারী সবচেয়ে বেশি।":"Người dùng tàu là nhiều nhất.","জি, বলুন।":"Vâng, xin mời nói.","শনিবার বিকেল হলে ঠিক আছে।":"Chiều thứ bảy thì được.","শুধু এই জরিপ থেকে তা বিচার করা যায় না।":"Chỉ từ khảo sát này thì không thể phán đoán điều đó."},"study.kanji":{"বোঝা বা সমাধান":"Hiểu hoặc giải quyết","তুলনা":"So sánh","দৃশ্য":"Phong cảnh","প্রত্যাশা":"Kỳ vọng","বৃদ্ধি":"Tăng","মিলিত সহযোগিতা":"Hợp tác chung","বাহিরে প্রকাশ":"Bộc lộ ra ngoài","অনুভূতি বা অবস্থা":"Cảm xúc hoặc trạng thái","অতিথি বা ক্রেতা":"Khách hoặc người mua","অভ্যস্ত":"Đã quen","মনের ভাব":"Suy nghĩ trong lòng","ধারণা বা চিন্তা":"Khái niệm hoặc suy nghĩ","বদলানো":"Thay đổi","বিবেচনা":"Cân nhắc","ভিন্ন":"Khác biệt","ভরসা":"Sự tin cậy","হ্রাস":"Giảm","রূপ বা ছাপ":"Hình dáng hoặc dấu ấn"},"study.listening_answer":{"এ সপ্তাহে প্রশ্ন তৈরি হবে; আগামী সপ্তাহে লাইব্রেরির প্রবেশপথে জরিপ হবে।":"Tuần này câu hỏi sẽ được tạo; tuần sau khảo sát sẽ diễn ra ở lối vào thư viện.","জীবনবৃত্তান্ত আনতে হবে; আগামী মঙ্গলবার বেলা ৩টার মধ্যে অফিসে আসতে হবে; পরিবর্তন চাইলে আগের দিনের মধ্যে ফোন করতে হবে।":"Phải mang theo sơ yếu lý lịch; phải đến văn phòng trước 3 giờ chiều thứ ba tới; nếu muốn thay đổi, phải gọi điện trước ngày hôm trước.","শনিবার বেলা ২টা; স্টেশনের সামনের লাইব্রেরি; শুক্রবারের মধ্যে জানাতে হবে।":"Thứ bảy lúc 2 giờ; thư viện trước ga; phải thông báo trước thứ sáu.","মঙ্গলবার বিকেলে পারবেন; সময়সূচি বদলানো যাবে কি না যাচাই করতে বলছেন।":"Anh ấy có thể vào chiều thứ ba; anh ấy đang yêu cầu kiểm tra xem có thể thay đổi lịch trình hay không.","সকালে ৬÷১০ = ৬০ শতাংশ; নির্দিষ্ট সময় নেই একজনের। এগুলো অনুশীলনের সংখ্যা।":"Buổi sáng 6÷10 = 60 phần trăm; một người không có thời gian cố định. Đây là các số liệu luyện tập.","গতকাল দোকানে যে আসনে বসেছিলেন সেখানে; আজ সন্ধ্যায় নিতে যাবেন।":"Ở chỗ ngồi hôm qua anh ấy ngồi trong cửa hàng; anh ấy sẽ đến lấy vào tối nay."},"study.listening_question":{"ব্যাগ কোথায় পাওয়া গেছে? বক্তা কখন নিতে যাবেন?":"Túi được tìm thấy ở đâu? Người nói sẽ đến lấy khi nào?","কী আনতে হবে, কখন আসতে হবে, পরিবর্তন চাইলে কী করবেন?":"Cần mang theo gì, phải đến khi nào, nếu muốn thay đổi thì làm thế nào?","সকালে পড়ার অনুপাত কত? নির্দিষ্ট সময় নেই কতজনের?":"Tỷ lệ đọc vào buổi sáng là bao nhiêu? Bao nhiêu người không có thời gian cố định?","কখন, কোথায় এবং কত দিনের মধ্যে জানাতে হবে?":"Phải thông báo khi nào, ở đâu và trong vòng bao nhiêu ngày?","এ সপ্তাহে কী হবে? জরিপ কোথায় এবং কখন হবে?":"Tuần này sẽ có gì? Khảo sát sẽ ở đâu và khi nào?","বক্তা কোন দিন পারবেন? শ্রোতার কাছে কী অনুরোধ করছেন?":"Người nói có thể vào ngày nào? Anh ấy đang yêu cầu người nghe điều gì?"},"study.questions":{"সবার কাছে একই ব্যাখ্যা যথেষ্ট নয় কেন?":"Tại sao cùng một lời giải thích không đủ với mọi người?","মিনা যাওয়ার আগে কী করেনি?":"Mina đã không làm gì trước khi đi?","গ্রাহকের প্রয়োজন অনুযায়ী ব্যাখ্যা মানিয়ে নেওয়া।":"Điều chỉnh lời giải thích theo nhu cầu của khách hàng.","প্রথমবার আসা ব্যক্তির উদাহরণটি কী বোঝায়?":"Ví dụ về người đến lần đầu diễn tả điều gì?","দৃষ্টিকোণ বদলানোর কারণ কী ছিল?":"Lý do thay đổi góc nhìn là gì?","লেখাটির মূল শিক্ষা কী?":"Bài học chính của bài viết là gì?","পরের বাক্যে কাজ থাকার কারণ ও রবিবারের বিকল্প দেওয়ার তথ্য থেকে।":"Từ thông tin ở câu sau về lý do có việc và việc đưa ra phương án chủ nhật.","ট্রেন ব্যবহারকারীর অনুপাত কত এবং কীভাবে পেলেন?":"Tỷ lệ người dùng tàu là bao nhiêu và bạn tính ra thế nào?","প্রথমে কাগজ বাড়াতে চেয়েছিল; পরে ব্যবহারকারীর প্রয়োজন বুঝে ভাষা সহজ করেছে।":"Ban đầu muốn tăng thêm giấy; sau đó hiểu nhu cầu của người dùng và làm ngôn ngữ đơn giản hơn.","খাতা পাওয়া গেছে বলে স্টেশনের খবর আসার পর।":"Sau khi tin từ nhà ga đến rằng cuốn sổ đã được tìm thấy.","না; আগামীকাল পারবে না, রবিবার পারবে বলে বিকল্প দিয়েছে।":"Không; anh ấy nói ngày mai không được, chủ nhật thì được, và đưa ra phương án thay thế.","ব্যবহারকারীদের সঙ্গে কথা বলে সমস্যাটি শ্রেণিবিভাগের নাম বুঝতে অসুবিধা বলে জানা যায়।":"Sau khi nói chuyện với người dùng, người ta biết vấn đề là khó hiểu tên phân loại.","আমন্ত্রণের ভাষা শুনে সময় ধরে না নিয়ে পরিস্থিতি যাচাই ও আলোচনা করা দরকার।":"Nghe ngôn ngữ của lời mời, không nên tự ý ấn định thời gian mà cần kiểm tra tình huống và thảo luận.","১২÷২০×১০০ = ৬০ শতাংশ।":"12÷20×100 = 60 phần trăm.","কোন ঘটনায় ইউয়ের অনুভূতি বদলাল?":"Cảm xúc của Yū thay đổi bởi sự kiện nào?","প্রথম প্রস্তাব ও শেষ পদক্ষেপ কীভাবে আলাদা?":"Đề xuất đầu tiên và bước đi cuối cùng khác nhau thế nào?","গ্রাহকের অভিজ্ঞতা ও চাহিদা আলাদা; সে অনুযায়ী ক্রম ও ভাষা বদলাতে হয়।":"Kinh nghiệm và nhu cầu của khách hàng khác nhau; phải thay đổi thứ tự và ngôn ngữ theo đó.","না; খাতা হারিয়ে ইউয়ের অনুভূতির উপমা। かのように সূত্রটি দেখুন।":"Không; đó là phép ẩn dụ cho cảm xúc của Yū khi mất cuốn sổ. Hãy xem manh mối かのように.","কথাগুলো মুছে যাওয়ার বর্ণনাটি কি বাস্তব ঘটনা?":"Mô tả về việc những lời bị xóa có phải là sự kiện thực tế không?","বন্ধুর সময় আছে কি না যোগাযোগ করে নিশ্চিত করেনি। দ্বিতীয় ও তৃতীয় বাক্য মিলিয়ে বুঝবেন।":"Cô ấy đã không liên lạc để xác nhận xem bạn có thời gian hay không. Hãy hiểu bằng cách kết hợp câu thứ hai và thứ ba.","難[むずか]しい-এর উদ্দেশ্য কোন তথ্য থেকে নিশ্চিত হলেন?":"Từ thông tin nào bạn xác định được ý của 難[むずか]しい?","এই কথোপকথনে বন্ধু কি সাহায্য একেবারে অস্বীকার করেছে?":"Trong cuộc hội thoại này, người bạn có hoàn toàn từ chối giúp đỡ không?","উত্তরদাতা কেবল একটি ক্লাসের ২০ জন; নমুনা জাতীয় প্রতিনিধিত্ব নিশ্চিত করে না।":"Người trả lời chỉ là 20 người của một lớp; mẫu không đảm bảo tính đại diện toàn quốc.","কেন সারা জাপানের বিষয়ে সিদ্ধান্ত নেওয়া যায় না?":"Tại sao không thể kết luận về toàn bộ Nhật Bản?"},"study.reading":{"たとえば-এর উদাহরণ আগের মানিয়ে নেওয়ার বক্তব্যকে স্পষ্ট করে।":"Ví dụ của たとえば làm rõ phát biểu điều chỉnh trước đó.","পরের কারণ ও বিকল্প দিন থেকে আগের কথার উদ্দেশ্য পরিষ্কার হয়।":"Từ nguyên nhân và ngày thay thế ở phía sau, mục đích của lời nói trước trở nên rõ ràng.","অন্য দৃষ্টিকোণ থেকে ভাবাই উন্নতির সূচনা হলো।":"Việc suy nghĩ từ góc nhìn khác chính là khởi đầu của sự cải tiến.","একটি ছোট দোকানের ম্যানেজারকে জিজ্ঞেস করলাম, কাজের কোন বিষয়টিকে গুরুত্ব দেন।":"Tôi đã hỏi quản lý của một cửa hàng nhỏ xem anh ấy coi trọng điều gì trong công việc.","কাগজ কম থাকা নয়, নামের অর্থ না বোঝা—সমস্যার ব্যাখ্যা বদলাল।":"Không phải thiếu giấy, mà là không hiểu nghĩa của tên — cách giải thích vấn đề đã thay đổi.","এই বাক্য গল্পের মোড় বদলায়; আগের উদ্বেগের বিপরীতে ভালো খবর।":"Câu này thay đổi bước ngoặt của câu chuyện; trái ngược với lo lắng trước đó, đây là tin tốt.","সমাধান হিসেবে আলোচনা এসেছে; কোনো দেশের সব মানুষকে নিয়ে নিয়ম বলা হয়নি।":"Thảo luận được đưa ra như một giải pháp; không có quy tắc nào được nói về tất cả mọi người của một quốc gia.","শেষ বাক্য ঘটনাটির সাধারণ শিক্ষা; উদাহরণের বাইরে অতিরিক্ত ফল দাবি করা হয়নি।":"Câu cuối là bài học chung của sự kiện; không có tuyên bố về kết quả thêm ngoài ví dụ.","ক্লাসের অনুশীলনের জন্য ধরে নিই, ২০ শিক্ষার্থীকে যাতায়াতের উপায় জিজ্ঞেস করা হলো।":"Để luyện tập trong lớp, giả sử 20 học sinh được hỏi về phương tiện đi lại.","ম্যানেজার বললেন, “একই ব্যাখ্যা বারবার বলাই যথেষ্ট নয়।”":"Quản lý nói: \"Chỉ lặp lại cùng một lời giải thích là chưa đủ.\"","তার মনে হলো, যেন গুরুত্বপূর্ণ কথাগুলোও হারিয়ে গেছে।":"Cô ấy cảm thấy như thể những lời quan trọng cũng đã mất đi.","しかし আগের প্রত্যাশার সঙ্গে বাস্তব অবস্থার অমিল আনে।":"しかし tạo ra sự không khớp giữa kỳ vọng trước đó và tình trạng thực tế.","এই দৃশ্যে কী বোঝায় বলা হয়েছে; সব ক্ষেত্রে একই অর্থ দাবি করা হয়নি।":"Trong cảnh này, điều nó diễn tả đã được nói; không có tuyên bố rằng mọi trường hợp đều có cùng một nghĩa.","খাতাটি হাতে পেয়ে ইউ না হেসে থাকতে পারল না।":"Nhận được cuốn sổ, Yū không thể không cười.","পরদিন স্টেশন থেকে জানানো হলো খাতাটি পাওয়া গেছে।":"Ngày hôm sau, nhà ga thông báo rằng cuốn sổ đã được tìm thấy.","দুজন সময়সূচি নিশ্চিত করার গুরুত্ব নিয়ে আলোচনা করল।":"Hai người đã thảo luận về tầm quan trọng của việc xác nhận lịch trình.","কিন্তু বন্ধু তখন কাজে বের হওয়ার ঠিক আগের অবস্থায় ছিল।":"Nhưng lúc đó người bạn đang ở trạng thái sắp ra ngoài đi làm.","তারপর বলল, “কাজ আছে, তবে রবিবার হলে সাহায্য করতে পারব।”":"Sau đó anh ấy nói: \"Tôi có việc, nhưng nếu là chủ nhật thì tôi có thể giúp.\"","এটি অনুশীলনের কাল্পনিক জরিপ; বাস্তব গবেষণা নয়।":"Đây là khảo sát giả định để luyện tập; không phải nghiên cứu thực tế.","বন্ধু বলল, “আগামীকাল একটু কঠিন হবে।”":"Người bạn nói: \"Ngày mai hơi khó.\"","প্রথম বাক্যে সমস্যাটি এসেছে; খাতাটির দৈনন্দিন গুরুত্বও জানা গেল।":"Vấn đề xuất hiện ở câu đầu; tầm quan trọng hằng ngày của cuốn sổ cũng được biết đến.","বাসায় পৌঁছানো মাত্র সে বিষয়টি টের পেল।":"Ngay khi về đến nhà, cô ấy nhận ra việc đó.","অনুরোধের বিষয় ও সময় আগে দেওয়া হয়েছে।":"Nội dung và thời gian của yêu cầu đã được nêu trước.","পরদিন সে কোনো যোগাযোগ না করেই বন্ধুর বাসায় গেল।":"Ngày hôm sau, cô ấy đến nhà bạn mà không liên lạc gì.","しかし উপসংহারের সীমা নির্দেশ করে।":"しかし chỉ ra giới hạn của kết luận.","মোট ১২+৫+৩=২০; গণনার ভিত্তি একই আছে।":"Tổng cộng 12+5+3=20; cơ sở tính toán vẫn giống nhau.","শেষ বাক্য লেখার মূল শিক্ষা।":"Câu cuối là bài học chính của bài viết.","最初[さいしょ]は প্রথম প্রস্তাব চিহ্নিত করছে; এটি চূড়ান্ত সমাধান নয়।":"最初[さいしょ]は đang đánh dấu đề xuất đầu tiên; đây không phải là giải pháp cuối cùng.","প্রথমে নির্দেশনার কাগজ বাড়ানোর কথা ভাবা হলো।":"Ban đầu, người ta nghĩ đến việc tăng thêm giấy hướng dẫn.","এই অভিজ্ঞতার মাধ্যমে মিনা কথার পাশাপাশি পরিস্থিতিও যাচাই করতে শুরু করল।":"Thông qua trải nghiệm này, Mina bắt đầu kiểm tra cả tình huống bên cạnh lời nói.","কারণ লক্ষ্যগোষ্ঠী কেবল একটি ক্লাস।":"Vì nhóm đối tượng chỉ là một lớp học.","১২ জন ট্রেন, ৫ জন সাইকেল এবং ৩ জন হেঁটে যাওয়ার কথা বলল।":"12 người nói đi tàu, 5 người đi xe đạp và 3 người đi bộ.","かのように উপমা; বাস্তবে সব কথা মুছে গেছে এমন তথ্য নয়।":"かのように là phép ẩn dụ; không phải thông tin rằng thực tế mọi lời đều đã bị xóa.","聞[き]きました-র প্রশ্নবিষয় দিয়ে পরের উত্তরের কেন্দ্র নির্ধারিত হয়।":"Chủ đề câu hỏi trong 聞[き]きました quyết định trọng tâm của câu trả lời tiếp theo.","ট্রেন ব্যবহারকারীর অনুপাত ৬০ শতাংশ।":"Tỷ lệ người dùng tàu là 60 phần trăm.","তাই কর্মীরা পরিচিত ভাষায় লেখা নির্দেশনা ব্যবহার করলেন।":"Vì vậy, nhân viên đã sử dụng hướng dẫn viết bằng ngôn ngữ quen thuộc.","এখানে 難[むずか]しい কেবল কাজের জটিলতা নাও বোঝাতে পারে।":"Ở đây, 難[むずか]しい có thể không chỉ có nghĩa là độ phức tạp của công việc.","を通[とお]して অভিজ্ঞতার মাধ্যমে শেখা; ようになった আচরণের পরিবর্তন।":"を通[とお]して là học thông qua trải nghiệm; ようになった là sự thay đổi trong hành vi.","に応[おう]じて মানিয়ে নেওয়া; そうです বক্তার কাছ থেকে শোনা তথ্য।":"に応[おう]じて là điều chỉnh cho phù hợp; そうです là thông tin được nghe lại.","たとたん পৌঁছানোর সঙ্গে হঠাৎ উপলব্ধি বোঝায়।":"たとたん diễn tả nhận thức đột ngột cùng lúc với việc đến nơi.","গ্রাহকের চাহিদা অনুযায়ী তিনি ব্যাখ্যার ক্রম ও ভাষা বদলান।":"Theo nhu cầu của khách hàng, anh ấy thay đổi thứ tự và ngôn ngữ giải thích.","ことなく মানে না করে; মিনার আগেই খবর না দেওয়া এখানে গুরুত্বপূর্ণ।":"ことなく có nghĩa là không làm; việc Mina không báo trước ở đây là quan trọng.","কেন এক বন্ধুকে পরদিন বাসা বদলে সাহায্য করতে বলল।":"Ken đã nhờ một người bạn giúp chuyển nhà vào ngày hôm sau.","শেষ বাক্য প্রতিবেদকের উপলব্ধি; ম্যানেজারের সরাসরি উদ্ধৃতি নয়।":"Câu cuối là nhận thức của người viết báo cáo; không phải trích dẫn trực tiếp của quản lý.","মনে হলো, মন দিয়ে অন্যের কথা শোনাই আস্থার শুরু।":"Tôi cảm thấy việc chăm chú lắng nghe người khác chính là khởi đầu của niềm tin.","শেষ প্রতিক্রিয়া থেকে স্বস্তি ও আনন্দ বোঝা যায়।":"Từ phản ứng cuối cùng có thể hiểu được sự nhẹ nhõm và niềm vui.","প্রথম বাক্যে বলা তথ্যটি আমন্ত্রণের ভাষা; এখনো সময় নির্দিষ্ট হয়নি।":"Thông tin được nói ở câu đầu là ngôn ngữ của lời mời; thời gian vẫn chưa được ấn định.","কিন্তু ব্যবহারকারীদের সঙ্গে কথা বলে জানা গেল, শ্রেণিবিভাগের নাম বোঝা কঠিন।":"Nhưng sau khi nói chuyện với người dùng, người ta biết rằng tên phân loại khó hiểu.","ইউ প্রতিদিন ব্যবহার করা খাতাটি ট্রেনে ফেলে এল।":"Yū đã để quên cuốn sổ dùng hằng ngày trên tàu.","だけでは十分[じゅうぶん]ではない সীমা দেখাচ্ছে; কোনো ব্যাখ্যাই প্রয়োজন নেই বলা হয়নি।":"だけでは十分[じゅうぶん]ではない đang chỉ ra một giới hạn; không có nghĩa là không cần bất kỳ lời giải thích nào.","এই পরিস্থিতিতে “কঠিন” কথাটি পরদিনের অনুরোধ প্রত্যাখ্যান করছে।":"Trong tình huống này, từ \"khó\" đang từ chối yêu cầu của ngày hôm sau.","অর্থ বুঝতে শব্দের পাশাপাশি প্রসঙ্গও জরুরি।":"Để hiểu nghĩa, bên cạnh từ ngữ, ngữ cảnh cũng quan trọng.","そこで আগের তথ্যের ভিত্তিতে করা পদক্ষেপকে যুক্ত করছে।":"そこで kết nối bước đi được thực hiện dựa trên thông tin trước đó.","মিনাকে এক বন্ধু বলল, “আবার বেড়াতে এসো।”":"Một người bạn nói với Mina: \"Lại đến chơi nhé.\"","にすぎない পরিসরের সীমাবদ্ধতা দেখায়।":"にすぎない cho thấy sự hạn chế của phạm vi.","একটি লাইব্রেরিতে বই খুঁজতে বেশি সময় লাগে বলে মতামত এসেছিল।":"Có ý kiến cho rằng ở một thư viện, việc tìm sách mất nhiều thời gian.","শুরুতে ব্যবহারকারীর সমস্যা তুলে ধরা হয়েছে।":"Ở đầu, vấn đề của người dùng được nêu ra.","১২÷২০×১০০=৬০; শুধু সংখ্যা নয়, মোটের ভিত্তি দেখুন।":"12÷20×100=60; đừng chỉ nhìn số, hãy nhìn cơ sở của tổng số.","তবে শুধু এই ফল দিয়ে জাপানের সব শিক্ষার্থী সম্পর্কে বলা যায় না।":"Tuy nhiên, chỉ với kết quả này thì không thể nói về tất cả học sinh Nhật Bản.","যেমন, প্রথমবার আসা ব্যক্তিকে ব্যবহারের পদ্ধতি দিয়ে বোঝানো শুরু করেন।":"Ví dụ, với người đến lần đầu, anh ấy bắt đầu giải thích bằng cách sử dụng."},"study.reading_title":{"“একটু কঠিন” কথাটির পর কী হলো":"Điều gì đã xảy ra sau câu nói “hơi khó”","সমস্যার বদলে প্রয়োজন থেকে ভাবা":"Suy nghĩ từ nhu cầu thay vì vấn đề","ভালো সেবা মানে একই উত্তর নয়":"Dịch vụ tốt không có nghĩa là cùng một câu trả lời","একটি আমন্ত্রণ, দুই রকম ধারণা":"Một lời mời, hai cách hiểu","হারানো খাতার ছোট গল্প":"Câu chuyện nhỏ về cuốn sổ bị mất","জরিপের সংখ্যা থেকে কতটুকু বলা যায়":"Từ các con số khảo sát, bạn có thể nói được đến đâu"},"study.strategy":{"শব্দের আক্ষরিক অর্থের পাশাপাশি কে, কাকে, কোন অনুরোধে বলছে তা দেখুন। পরোক্ষ কথাকে সবার জন্য স্থির নিয়ম হিসেবে ধরবেন না।":"Bên cạnh nghĩa đen của từ, hãy xem ai đang nói, nói với ai, với yêu cầu nào. Đừng coi lời nói gián tiếp là quy tắc cố định cho mọi người.","শিরোনাম ও ছোট উপশিরোনাম দেখে যুক্তির ধাপ ধরুন। দাবি, কারণ, উদাহরণ ও বিকল্পকে আলাদা করুন। মতের বিরোধিতা করলে কারণসহ বিকল্প দিন।":"Hãy xem tiêu đề và tiểu tiêu đề nhỏ để nắm bắt các bước lập luận. Tách riêng khẳng định, lý do, ví dụ và phương án thay thế. Khi phản đối ý kiến, hãy đưa ra phương án thay thế kèm lý do.","চরিত্রের অনুভূতি কোন ঘটনা বা শব্দে বদলেছে তা দেখুন। উপমাকে বাস্তব ঘটনা হিসেবে নেবেন না। পর্যালোচনায় নিজের মূল্যায়নের কারণ দিন।":"Hãy xem cảm xúc của nhân vật đã thay đổi bởi sự kiện hoặc từ ngữ nào. Đừng coi phép ẩn dụ là sự kiện thực tế. Trong phần nhìn lại, hãy nêu lý do cho đánh giá của bạn.","প্রশ্নের উত্তরে বক্তা প্রথমে সিদ্ধান্ত বলেছেন, না উদাহরণ দিয়েছেন, তা ধরুন। উদাহরণ কোন মূল কথাকে বোঝাচ্ছে সেটি খুঁজুন।":"Hãy nắm bắt xem trong câu trả lời, người nói nói kết luận trước hay đưa ví dụ trước. Tìm xem ví dụ đang diễn tả ý chính nào.","বাক্যে কর্তা বাদ গেলে আগের বাক্য ও কথোপকথনের প্রবাহ দেখুন। অনুমান আর স্পষ্টভাবে বলা তথ্য আলাদা রাখুন।":"Khi chủ thể bị lược bỏ trong câu, hãy xem câu trước và mạch hội thoại. Giữ riêng suy đoán và thông tin được nói rõ ràng.","জরিপের লক্ষ্যগোষ্ঠী, মোট উত্তরদাতা, সময় ও শতাংশের ভিত্তি আগে পড়ুন। উদাহরণের সংখ্যাকে বাস্তব জরিপের ফল হিসেবে ব্যবহার করবেন না।":"Hãy đọc trước nhóm đối tượng của khảo sát, tổng số người trả lời, thời gian và cơ sở của tỷ lệ phần trăm. Đừng dùng số liệu ví dụ làm kết quả khảo sát thực tế."},"study.vocab":{"প্রকাশভঙ্গি":"Cách diễn đạt","দৃষ্টিকোণ":"Góc nhìn","ভুল বোঝাবুঝি":"Hiểu lầm","অনুভূতি":"Cảm xúc","আস্থা":"Niềm tin","উদ্বেগ":"Lo lắng","অভিজ্ঞতা":"Kinh nghiệm","লক্ষ্যগোষ্ঠী বা বিষয়":"Nhóm đối tượng hoặc chủ đề","জরিপ বা অনুসন্ধান":"Khảo sát hoặc điều tra","অনুপাত":"Tỷ lệ","উদ্দেশ্য":"Mục đích","অন্যের কথা বিবেচনা":"Cân nhắc lời của người khác","প্রসঙ্গ":"Ngữ cảnh","ভূমিকা":"Vai trò","সংকোচ বা সংযম":"Ngại ngùng hoặc kiềm chế","চিন্তার সূচনা বা ধারণা":"Khởi đầu của suy nghĩ hoặc khái niệm","পারস্পরিক আদানপ্রদান":"Trao đổi lẫn nhau","কৌশল বা বুদ্ধিদীপ্ত চেষ্টা":"Chiến lược hoặc nỗ lực khéo léo","সহযোগিতা":"Hợp tác","চাহিদা বা আশা":"Nhu cầu hoặc kỳ vọng","ভিন্ন সংস্কৃতি":"Văn hóa khác biệt","প্রস্তাব":"Đề xuất","অভ্যাস বা রীতি":"Thói quen hoặc phong tục","স্বস্তি":"Nhẹ nhõm","গ্রাহকসেবা":"Dịch vụ khách hàng","হ্রাস":"Giảm","মনের ওপর ছাপ":"Ấn tượng trong tâm trí","বৃদ্ধি":"Tăng","তুলনা":"So sánh","গল্প বা আখ্যান":"Câu chuyện hoặc truyện kể","দৃশ্য বা পরিস্থিতি":"Cảnh hoặc tình huống","যাচাই করা":"Kiểm tra, xác minh","প্রত্যাখ্যান করা":"Từ chối","উন্নতি":"Cải thiện, tiến bộ","জানানো":"Thông báo"},"study.writing":{"আমি খাতা হারানো একজনের ছোট গল্প পড়েছি।":"Tôi đã đọc một câu chuyện ngắn về một người làm mất cuốn sổ.","ট্রেন ব্যবহারকারী ১২ জন, যা সবচেয়ে বড় অংশ।":"Người dùng tàu là 12 người, là phần lớn nhất.","কিন্তু বন্ধু ভেবেছিল এখনো আলোচনা দরকার।":"Nhưng bạn tôi nghĩ vẫn cần thảo luận.","আমারও প্রিয় জিনিস হারানোর অভিজ্ঞতা আছে বলে অনুভূতিটি বুঝেছি।":"Vì tôi cũng có trải nghiệm làm mất món đồ yêu thích nên tôi hiểu được cảm xúc đó.","অনুশীলনের জরিপে একটি ক্লাসের ২০ শিক্ষার্থীকে প্রশ্ন করা হয়েছে।":"Trong khảo sát luyện tập, 20 học sinh của một lớp đã được hỏi.","এই অভিজ্ঞতার পর গুরুত্বপূর্ণ বিষয় স্পষ্টভাবে বলে নিশ্চিত করার চেষ্টা করি।":"Sau trải nghiệm này, tôi cố gắng nói rõ những việc quan trọng và xác nhận lại.","মূল চরিত্রের উদ্বেগ পরিচিত ভাষায় তুলে ধরা হয়েছে।":"Nỗi lo của nhân vật chính được thể hiện bằng ngôn ngữ quen thuộc.","যেমন কঠিন শব্দ পরিচিত প্রকাশে বদলে দেওয়া যায়।":"Ví dụ, từ khó có thể thay bằng cách diễn đạt quen thuộc.","তাই যারা ব্যবহার করবেন তাঁদের মতামত শোনা উচিত বলে মনে করি।":"Vì vậy, tôi nghĩ nên lắng nghe ý kiến của những người sẽ sử dụng.","এটি এমন গল্প যা দৈনন্দিন ছোট ঘটনাকেও গুরুত্ব দিতে শেখায়।":"Đây là câu chuyện dạy ta coi trọng cả những sự kiện nhỏ hằng ngày.","আমি ভেবেছিলাম সময় ঠিক হয়ে গেছে।":"Tôi đã nghĩ thời gian đã được ấn định.","সম্পর্ক ও পরিস্থিতি অনুযায়ী তা বদলায়।":"Nó thay đổi theo mối quan hệ và tình huống.","আমার মতে নির্দেশনা তৈরির সময় ব্যবহারকারীর দৃষ্টিকোণ জরুরি।":"Theo tôi, khi làm hướng dẫn, góc nhìn của người dùng là quan trọng.","দীর্ঘ অভিজ্ঞতার ভিত্তিতে তিনি বোঝানোর ধরনে কৌশল ব্যবহার করেন।":"Dựa trên kinh nghiệm lâu năm, anh ấy sử dụng chiến lược trong cách giải thích.","তাঁর মতে সবচেয়ে গুরুত্বপূর্ণ হলো গ্রাহকের কথা শোনা।":"Theo anh ấy, điều quan trọng nhất là lắng nghe khách hàng.","আমি পাশের দোকানের ম্যানেজারের সাক্ষাৎকার নিয়েছি।":"Tôi đã phỏng vấn quản lý của cửa hàng bên cạnh.","জাপানিতে কোনো সময় না করার আগে কারণ বলা হয়।":"Trong tiếng Nhật, trước khi nói không làm vào một thời điểm nào đó, người ta nêu lý do.","না বুঝলে আমি ভদ্রভাবে নিশ্চিত হতে চাই।":"Nếu không hiểu, tôi muốn xác nhận lại một cách lịch sự.","আমিও অন্যের অবস্থান বিবেচনা করে কাজ করতে চাই বলে মনে হয়েছে।":"Tôi cũng cảm thấy muốn làm việc có cân nhắc vị trí của người khác.","তবে সবসময় একই প্রকাশ ব্যবহার হয় না।":"Tuy nhiên, không phải lúc nào cũng dùng cùng một cách diễn đạt.","জাপানে নতুন আসার সময় এক বন্ধুর সঙ্গে কথা দেওয়া নিয়ে সমস্যায় পড়েছিলাম।":"Khi mới đến Nhật, tôi đã gặp rắc rối về việc hứa hẹn với một người bạn.","সাইকেল ব্যবহারকারীর তুলনায় ৭ জন বেশি।":"Nhiều hơn 7 người so với người dùng xe đạp.","কারণ তথ্য বেশি হলেই অর্থ পরিষ্কার হয় এমন নয়।":"Vì không phải thông tin nhiều thì nghĩa sẽ rõ ràng.","তবে অল্পসংখ্যক ব্যক্তির ফল বলে এটি সামগ্রিক প্রবণতা নাও হতে পারে।":"Tuy nhiên, vì đây là kết quả của số ít người, nó có thể không phải là xu hướng chung."},"study.writing_prompt":{"নিজের একটি ভুল বোঝাবুঝির অভিজ্ঞতা লিখুন: ঘটনা → নিজের ধারণা → অন্য পক্ষের অবস্থা → পরেরবার কী করবেন।":"Hãy viết một trải nghiệm hiểu lầm của bạn: sự việc → suy nghĩ của bạn → tình trạng của phía bên kia → lần sau bạn sẽ làm gì.","বাংলা ও জাপানিতে কোনো অনুরোধ ফিরিয়ে দেওয়ার একটি করে উদাহরণ দিন। শব্দের অর্থ, সম্পর্ক ও পরিস্থিতি আলাদা করে লিখুন; জাতিগত সাধারণীকরণ এড়িয়ে চলুন।":"Hãy đưa một ví dụ về việc từ chối yêu cầu bằng tiếng Bengali và một ví dụ bằng tiếng Nhật. Viết riêng nghĩa của từ, mối quan hệ và tình huống; tránh khái quát hóa theo dân tộc.","একটি গল্প বা সিনেমার সংক্ষিপ্ত রিভিউ লিখুন: পরিচয় → একটি দৃশ্য → নিজের অনুভূতি → সুপারিশের কারণ। সমাপ্তির সব তথ্য বলে দেবেন না।":"Hãy viết một bài review ngắn về một câu chuyện hoặc bộ phim: giới thiệu → một cảnh → cảm xúc của bạn → lý do giới thiệu. Đừng nói hết mọi thông tin về kết thúc.","এই কাল্পনিক সংখ্যাগুলো ব্যবহার করে চার বাক্যের প্রতিবেদন লিখুন। লক্ষ্যগোষ্ঠী → সবচেয়ে বড় অংশ → তুলনা → সিদ্ধান্তের সীমা।":"Hãy dùng các số liệu giả định này để viết báo cáo bốn câu. Nhóm đối tượng → phần lớn nhất → so sánh → giới hạn của kết luận.","একটি ছোট সমস্যা বেছে ১৮০–২৫০ জাপানি অক্ষরে মতামত লিখুন: দাবি → কারণ → উদাহরণ → সম্ভাব্য আপত্তি → বাস্তব প্রস্তাব।":"Chọn một vấn đề nhỏ và viết ý kiến trong 180–250 ký tự tiếng Nhật: khẳng định → lý do → ví dụ → phản đối có thể có → đề xuất thực tế.","কোনো পরিচিত ব্যক্তির কাজ সম্পর্কে তিনটি প্রশ্ন করুন। সরাসরি উক্তি এবং নিজের উপলব্ধি আলাদা করে একটি ছোট প্রতিবেদন লিখুন।":"Hãy đặt ba câu hỏi về công việc của một người quen. Viết một báo cáo ngắn, tách riêng lời nói trực tiếp và nhận thức của bạn."},"title":{"QUARTET II · বাংলা গ্রামার সহায়িকা":"QUARTET II · Hướng dẫn ngữ pháp"}},"qa":{"attr.aside@aria-label":{"পাঠ নির্বাচন":"Chọn bài học"},"attr.div@aria-label":{"পড়ার ধরন":"Kiểu đọc"},"attr.input@aria-label":{"গ্রামার খুঁজুন":"Tìm ngữ pháp"},"attr.meta@description":{"QUARTET Ⅱ-এর অধ্যায় ৭–১২-এর থিমে নির্বাচিত ৩৬টি বিষয়ে নিজস্ব বাংলা ব্যাখ্যা, ফুরিগানাসহ উদাহরণ ও অনুশীলন।":"Giải thích bằng tiếng Việt do chính tác giả biên soạn, ví dụ có furigana và bài luyện tập về 36 chủ đề được chọn theo chủ đề của các chương 7–12 trong QUARTET Ⅱ."},"attr.nav@aria-label":{"এই অধ্যায়ের গ্রামার":"Ngữ pháp của chương này","QUARTET বই ও পড়ার ধরন":"Sách QUARTET và cách đọc","পথ নির্দেশনা":"Điều hướng đường đi"},"attr.progress@aria-label":{"গ্রামার শেখার অগ্রগতি":"Tiến độ học ngữ pháp"},"text.uncovered":{"পাঠ ও অনুশীলন খুলতে JavaScript চালু করুন।":"Hãy bật JavaScript để mở bài học và luyện tập.","N2 Grammar পড়ুন":"Đọc N2 Grammar"}}};
